flowchart TB
  subgraph T1["1 要件を数字に"]
    RQ["RPO と RTO<br/>単一障害点を探す"]
  end
  subgraph T2["2 AZ をまたぐ"]
    CO@{ svc: "Amazon EC2 Auto Scaling", label: "計算の層<br/>Auto Scaling・ELB<br/>NAT gateway" }
    DA@{ svc: "Amazon RDS", label: "データの層<br/>RDS・ElastiCache<br/>Multi-AZ" }
  end
  subgraph T3["3 Region をまたぐ"]
    AU@{ svc: "Amazon Aurora", label: "Aurora<br/>Global Database" }
    DD@{ svc: "Amazon DynamoDB", label: "DynamoDB<br/>global tables" }
    S3@{ svc: "Amazon S3", label: "S3 の複製<br/>RDS の read replica" }
    RT@{ svc: "Amazon Route 53", label: "Route 53・CloudFront<br/>warm standby" }
  end
  T1 ~~~ T2
  T2 ~~~ T3

flowchart TB
  AS@{ svc: "Amazon EC2 Auto Scaling", label: "EC2 Auto Scaling<br/>有効な AZ に同じ数" }
