  AS -- "数をそろえる" --> EB
  AS -- "数をそろえる" --> EA

flowchart TB
  subgraph T1["1 要件を数字に"]
    RQ["RPO と RTO<br/>単一障害点を直す"]
  end
  subgraph T2["2 AZ をまたぐ"]
    CO@{ svc: "Amazon EC2 Auto Scaling", label: "計算の層<br/>AZ に同じ数<br/>cross-zone<br/>AZ ごとの NAT" }
    DA@{ svc: "Amazon RDS", label: "データの層<br/>DB cluster は読める<br/>ElastiCache は昇格" }
  end
  subgraph T3["3 Region をまたぐ"]
    AU@{ svc: "Amazon Aurora", label: "Aurora<br/>switchover と failover" }
    DD@{ svc: "Amazon DynamoDB", label: "DynamoDB<br/>どこでも読み書き" }
    S3@{ svc: "Amazon S3", label: "S3 RTC<br/>15 分・SLA" }
    RT@{ svc: "Amazon Route 53", label: "Route 53・CloudFront<br/>健全でなければ予備へ" }
  end
